function TeamList() {
  const [members, setMembers] = useState([]);
  const addMember = () => {
    setMembers([...members, 'New Member']);
  };
  return (
    <div>
      <ul>
        {members.map((member, index) => (
          <li key={index}>{member}</li>
        ))}
      </ul>
      <button onClick={addMember}>Add Member</button>
    </div>
  );
}

